// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"Desde dónde tiene que escribir.","type":"El papel"},{"s":"El verbo exacto, uno solo por encargo.","type":"La tarea"},{"s":"Lo que solo tú sabes del trabajo.","type":"El contexto"},{"s":"En qué forma, de qué tamaño y para dónde va.","type":"El formato de salida"},{"s":"La muestra que se pega entera.","type":"El ejemplo"},{"s":"Lo que no debe hacer, dicho antes.","type":"Las restricciones"},{"s":"Cómo se sabrá que está bien y quién lo mide.","type":"El criterio de aceptación"},{"s":"Pedir el tema y nada más.","type":"Petición"},{"s":"Juntar el trabajo y pedirlo de una vez.","type":"Tanda grande"},{"s":"Arreglar la respuesta y dejar el encargo igual.","type":"Parche a mano"}];
const classifyTaskDB=[{"w":"Ordena esta lista por fecha y devuélvela en tabla","gen":"Instrucción","n":"Verbo claro","g":"Encargo","t":"Otro podría hacerlo sin preguntar"},{"w":"Hazme algo bonito para la portada","gen":"Instrucción","n":"Deseo","g":"Petición","t":"Hay que adivinar lo que querías"},{"w":"Parte la ficha en diez páginas de 215 a 252 mm","gen":"Instrucción","n":"Medible","g":"Encargo","t":"Se puede aprobar o reprobar"},{"w":"Ponlo más profesional","gen":"Instrucción","n":"Adjetivo","g":"Petición","t":"No dice qué cambiar ni cómo se mide"},{"w":"Escribir el primer borrador de una misión","gen":"Trabajo","n":"Se corrige barato","g":"Se le encarga","t":"Tú lo lees y lo arreglas"},{"w":"Contar las páginas del PDF","gen":"Trabajo","n":"Medición","g":"No se le encarga","t":"Medir es contar, no predecir"},{"w":"La cuenta exacta de los costos del mes","gen":"Trabajo","n":"Número","g":"No se le encarga","t":"Sale de los recibos, no del texto"},{"w":"Adjuntar el archivo que no se adjuntó","gen":"Arreglo","n":"En la instrucción","g":"Corrige el encargo","t":"La próxima vez ya sale bien"},{"w":"Quitar los guiones a mano uno por uno","gen":"Arreglo","n":"En la respuesta","g":"Parcha la respuesta","t":"El encargo queda igual de malo"},{"w":"Guardar el encargo que funcionó","gen":"Arreglo","n":"Se acumula","g":"Corrige el encargo","t":"Sirve en las seis misiones del año"}];
const completeTaskDB=[{"s":"Lo que solo tú sabes del trabajo es el ___.","opts":["contexto","papel","formato"],"ans":"contexto"},{"s":"La muestra que se pega entera es el ___.","opts":["formato","ejemplo","criterio"],"ans":"ejemplo"},{"s":"Lo que no debe hacer, dicho antes, es una ___.","opts":["tarea","salida","restricción"],"ans":"restricción"},{"s":"Cómo se sabrá que está bien es el ___.","opts":["criterio","papel","molde"],"ans":"criterio"},{"s":"Cuando sale mal se corrige el ___.","opts":["encargo","resultado","formato"],"ans":"encargo"},{"s":"Pedir el tema y nada más es una ___.","opts":["tanda","petición","pauta"],"ans":"petición"},{"s":"Juntar el trabajo y pedirlo de una vez es una ___.","opts":["vuelta","tanda","lista"],"ans":"tanda"},{"s":"Si le falta un dato para terminar, tiene que ___.","opts":["inventarlo","preguntarlo","saltarlo"],"ans":"preguntarlo"}];
const explainQuestions=[{"q":"Explica la diferencia entre una petición y un encargo, y di con qué prueba se sabe cuál de las dos escribiste.","ans":"Una petición dice el tema y nada más: «hazme algo bonito para la misión». Un encargo dice qué, para quién, con qué forma y con qué límite, así que se parece más a una orden de trabajo que a una pregunta. La diferencia no es de largo ni de educación: es que el encargo se puede aprobar o reprobar, porque trae escrito cuándo está terminado. Y la prueba es una sola: otra persona podría hacer ese trabajo sin preguntarte nada. Si para hacerlo hay que adivinar algo que solo tú sabes, todavía es una petición, aunque tenga tres párrafos."},{"q":"¿Por qué el contexto decide casi todo el resultado, y qué va siempre en el contexto de un encargo de M.E.T.A.S?","ans":"Porque la máquina no adivina lo que está en tu cabeza: contesta con lo que le cabe en la mesa, y lo que no le pusiste ahí lo rellena con lo más probable. Tiene millones de textos ajenos y cero información sobre tu proyecto, tu norma 6, tu maestra de Comayagua y lo que ya se decidió el martes. Si no se lo escribes, no existe. En un encargo de M.E.T.A.S va siempre el molde de la misión anterior adjunto, las normas 1-bis, 3, 4 y 6, la materia, la ruta y la etapa, quién lo va a leer (maestras de primaria en Honduras, madres con datos escasos, directores) y lo que ya está decidido, para que no lo vuelva a proponer. Y el archivo se adjunta: describir un archivo no es darlo."},{"q":"Se pidió una ficha de diez páginas, contestó que estaba lista y el PDF trajo diecinueve. Explica por qué es un fallo del encargo y escribe el criterio como debía ir.","ans":"No fue una mentira: fue un criterio que ella no podía comprobar sola. Medir es contar, y lo que hace la máquina es predecir texto, así que cuando le pides diez páginas sin decir cómo se miden, contesta que sí de buena fe. El fallo costó dinero de verdad: 30 juegos impresos a L 2 la página, L 1.140 en vez de L 600, o sea L 540 de sobrecosto. El criterio correcto nombra el instrumento y a quien lo usa: cada página entre 215 y 252 mm, letra de impresión de 10 pt, medido con el medidor de páginas y confirmado contando las hojas del PDF antes de mandar a imprimir. De ahí salió la norma 6 de la casa: el PDF es el único juez."},{"q":"¿Por qué un ejemplo pegado vale más que tres párrafos explicando el estilo?","ans":"Porque el ejemplo enseña tono, largo, forma y nivel de detalle todo a la vez, y sin discutir qué significa cada palabra. Los adjetivos no se pueden comprobar: «que quede claro», «profesional», «cercano» se interpretan, y casi nunca como tú lo pensabas. Se pega la muestra completa, no un pedazo, y se dice qué de ella hay que imitar y qué no, porque si no imita también el tema. Un contraejemplo («así no») sirve igual de bien. Y hay una trampa que se repite: pegar tres ejemplos distintos entre sí y esperar que adivine el patrón; con tres formas distintas la más probable es la del promedio, que no es ninguna de las tres. La regla de la casa es corta: antes de explicar el estilo, pegar una muestra."},{"q":"Devolvió una tabla de costos con L 4.800 de servidor, cifra que nunca vio. Escribe las dos restricciones que salvan el caso y explica por qué hacen falta las dos.","ans":"La primera es «si te falta un dato, pregúntamelo, no lo inventes». La segunda es «al final, devuélveme la lista de lo que no pudiste verificar con lo que te di». Hacen falta las dos porque prohibir la invención sin dar permiso de preguntar no sirve de nada: si le falta un dato para terminar y no tiene salida, rellena con lo más probable, y lo hace con la misma seguridad con la que acierta. La lista de lo no verificado es el mejor invento de esta etapa, porque convierte una invención en una pregunta contestable: en vez de una celda falsa que se ve igual que las verdaderas, queda una línea que dice «esto no lo pude comprobar». Con los recibos adjuntos, el servidor de ese mes eran L 1.150, no L 4.800, y esa tabla iba a una reunión con un director y con tu nombre encima."},{"q":"Explica por qué cuando el resultado sale mal se corrige el encargo y no la respuesta, y qué se guarda al final del día.","ans":"Porque el parche a mano arregla una vez y no deja rastro: el encargo queda igual de malo, así que la próxima misión llega con el mismo error y la tarde se repite. A las diez de la noche arreglar los guiones a mano se ve más rápido que volver a explicar todo, y es cierto para esa noche y falso para el mes. Corregir el encargo es buscar cuál de las siete casillas estaba vacía o floja, llenarla y volver a pedirlo completo con el material otra vez adjunto. Y lo que se guarda es el encargo, no la respuesta: la respuesta sirve para una misión y caduca; el encargo se vuelve a usar, mejora en cada vuelta y es lo único que se acumula. El de los 32 bancos costó dos horas escribirlo (L 500) y ahorró L 3.750 en las seis misiones del año. La colección de encargos es el activo, no la colección de respuestas."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

