// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🎭","label":"El papel","text":"¿Desde <strong>dónde</strong> tiene que escribir? <strong>Decide:</strong> el vocabulario, el nivel y qué da por sabido. <strong>Se rompe:</strong> al no ponerlo y recibir un texto de folleto corporativo. <strong>En M.E.T.A.S:</strong> «eres el que redacta las misiones de F.A.R.O y conoce las normas de la casa», no «eres un experto en educación»."},{"y":"2","icon":"🔨","label":"La tarea","text":"¿Qué <strong>verbo</strong> exacto? <strong>Decide:</strong> qué va a hacer y qué no. <strong>Se rompe:</strong> con verbos de humo: «mejora», «trabaja», «hazme algo con». <strong>En M.E.T.A.S:</strong> escribe, ordena, compara, traduce, parte en diez, cuenta. Un verbo por encargo."},{"y":"3","icon":"🧳","label":"El contexto","text":"¿Qué sé yo que <strong>ella no puede saber</strong>? <strong>Decide:</strong> casi todo el resultado. <strong>Se rompe:</strong> cuando el dato vive en tu cabeza o en un archivo que no adjuntaste. <strong>En M.E.T.A.S:</strong> el molde de la misión anterior, las normas 1-bis, 3, 4 y 6, quién lo va a leer y lo que ya se decidió."},{"y":"4","icon":"📐","label":"El formato de salida","text":"¿En qué <strong>forma</strong> y de qué tamaño? <strong>Decide:</strong> si sirve tal cual o hay que rehacerlo. <strong>Se rompe:</strong> al no decirlo y recibir tres páginas donde hacían falta diez líneas. <strong>En M.E.T.A.S:</strong> «diez líneas», «un archivo .js con el objeto B», «una tabla de tres columnas», «para pegar en la ficha»."},{"y":"5","icon":"🪞","label":"El ejemplo","text":"¿Con qué se <strong>parece</strong> a lo que quiero? <strong>Decide:</strong> el tono, el nivel de detalle y la forma, de un golpe. <strong>Se rompe:</strong> al describir el estilo con adjetivos en vez de pegar una muestra. <strong>En M.E.T.A.S:</strong> se pega un caso ya aprobado y se dice «así, con esta forma, para este otro tema»."},{"y":"6","icon":"🚧","label":"Las restricciones","text":"¿Qué <strong>no</strong> debe hacer, y qué hace si le falta un dato? <strong>Decide:</strong> los errores que ni siquiera ocurren. <strong>Se rompe:</strong> al callarlas y descubrirlas en el resultado. <strong>En M.E.T.A.S:</strong> «ni un guion largo», «nada de datos de menores», y sobre todo: «si te falta un dato, pregúntamelo, no lo inventes»."},{"y":"7","icon":"✅","label":"El criterio de aceptación","text":"¿Cómo se sabrá que <strong>está bien</strong>, y quién lo mide? <strong>Decide:</strong> cuándo el trabajo está terminado. <strong>Se rompe:</strong> con criterios que la máquina no puede comprobar por sí sola. <strong>En M.E.T.A.S:</strong> «diez páginas medidas con el medidor y confirmadas en el PDF», no «que quede de diez páginas»."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🔁</span><span class="ms-text"><strong>Reescribiste el encargo con las siete piezas:</strong> veinte minutos de escritura y una sola tanda de L 180.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🗂️</span><span class="ms-text"><strong>Salió a la primera:</strong> con las cifras del proyecto y sin un guion largo. Y el encargo quedó guardado: la próxima misión arranca desde ahí.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🩹</span><span class="ms-text"><strong>Los arreglaste a mano:</strong> dos horas de tu tiempo (L 500) a las diez de la noche, y ni una línea escrita para la próxima.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔂</span><span class="ms-text"><strong>Y el encargo quedó igual de malo:</strong> la próxima misión vas a recibir exactamente lo mismo, y lo vas a volver a arreglar a mano.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"contexto":{"nombre":"El contexto","icon":"🧳","estructura":{"title":"Qué es","info":"• Lo que <strong>solo tú sabes</strong> del trabajo<br>• El proyecto, quién lo va a leer y lo que ya se decidió<br>• No es «más texto»: es lo que ella no tiene forma de averiguar"},"funcion":{"title":"Cómo se escribe","info":"• Se lista lo decidido, con fecha si importa<br>• Se <strong>adjunta el archivo</strong>, no se describe el archivo<br>• Se dice para quién es el resultado y qué va a hacer con él"},"enfermedades":{"title":"Dónde se rompe","info":"• Cuando el dato vive en tu cabeza y das por hecho que se entiende<br>• Al pedir que arregle algo <strong>sin dar la cosa que hay que arreglar</strong><br>• Al mandar solo el pedazo y esperar coherencia con el resto"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Va siempre: el <strong>molde de la misión anterior</strong>, las normas 1-bis, 3, 4 y 6, la materia, la ruta y la etapa<br>• Público: maestras de primaria en Honduras, madres con datos escasos, directores<br>• Y lo que ya está decidido, para que no lo vuelva a proponer"}},"ejemplo":{"nombre":"El ejemplo","icon":"🪞","estructura":{"title":"Qué es","info":"• Una <strong>muestra</strong> de lo que quieres, no una descripción<br>• Un solo ejemplo bien elegido reemplaza una página de instrucciones<br>• Enseña tono, largo, forma y nivel de detalle a la vez"},"funcion":{"title":"Cómo se escribe","info":"• Se pega <strong>completo</strong>, no un pedazo<br>• Se dice qué de ese ejemplo hay que imitar y qué no<br>• Si hay un contraejemplo («así no»), también sirve, y mucho"},"enfermedades":{"title":"Dónde se rompe","info":"• Al describir el estilo con adjetivos: «que quede bonito», «profesional»<br>• Al pegar un ejemplo que en realidad no te gustaba<br>• Al dar tres ejemplos distintos entre sí y esperar que adivine el patrón"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• El caso 4 de la misión de datos, pegado entero, sirve de molde para los ocho casos de cualquier etapa nueva<br>• Regla de la casa: <strong>antes de explicar el estilo, pegar una muestra</strong>"}},"restricciones":{"nombre":"Las restricciones","icon":"🚧","estructura":{"title":"Qué es","info":"• Lo que <strong>no debe hacer</strong>, dicho antes<br>• Y qué hacer si le falta un dato para terminar<br>• Cada restricción es un error que ya no va a ocurrir"},"funcion":{"title":"Cómo se escribe","info":"• En negativo y en concreto: «ni un guion largo», no «cuida el estilo»<br>• Con la salida de emergencia: <strong>«si te falta un dato, pregúntamelo, no lo inventes»</strong><br>• Y con la devolución: «al final, la lista de lo que no pudiste verificar»"},"enfermedades":{"title":"Dónde se rompe","info":"• Al no ponerlas y pasar la tarde corrigiendo lo mismo de siempre<br>• Al ponerlas tan generales que no se pueden comprobar<br>• Al pedir que no invente <strong>sin darle permiso de preguntar</strong>: si no puede preguntar, rellena"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Las tres fijas: <strong>sin guion largo</strong>, <strong>sin datos de menores</strong>, <strong>cifras en lempiras</strong><br>• Y la cuarta, la que más sirve: que pregunte en vez de inventar"}},"criterio":{"nombre":"El criterio de aceptación","icon":"✅","estructura":{"title":"Qué es","info":"• Cómo se sabrá que el trabajo <strong>está bien</strong><br>• Escrito antes de empezar, no discutido después<br>• Incluye <strong>quién lo mide y con qué</strong>"},"funcion":{"title":"Cómo se escribe","info":"• Una condición comprobable: un número, un archivo, un comando<br>• Se nombra el instrumento: el medidor, el PDF, node --check, el grep<br>• Se dice qué pasa si no se cumple: se corrige el encargo y se repite"},"enfermedades":{"title":"Dónde se rompe","info":"• Con criterios que la máquina <strong>no puede medir sola</strong>: páginas, tamaños, cantidades<br>• Con «que quede bien», que no se puede aprobar ni reprobar<br>• Al aceptar la palabra de la máquina como si fuera la medición"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• La norma 6 nació de aquí: se pidieron <strong>diez páginas sin decir cómo se miden</strong> y el PDF trajo diecinueve<br>• Hoy el criterio dice: diez páginas medidas con mide-ficha-paginas.html y confirmadas en el PDF<br>• <strong>El PDF es el único juez</strong>"}}};
let labParte='contexto',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue puliendo tu encargo!','¡Muy buen trabajo!','¡Ya distingues encargo de petición!','¡Escribes encargos que salen a la primera!','¡Dueño de tu colección de encargos!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='📝 ¡'+name+' completó la Etapa 2 de la Ruta de la Máquina que Predice (Pedir bien)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

